#!/usr/bin/env python3
"""Generate gauge6_point_db.cpp: double-buffered cp.async overlap.

Prefetch var v+1 into the idle su buffer while algebra for var v runs
(after stencil grads are in registers). Target: beat PT_ASYNC on GB200.
"""
from __future__ import annotations

import re
from pathlib import Path

HERE = Path(__file__).resolve().parent

HEADER = """\
// Auto-generated by gen_gauge6_point_db.py — double-buffered cp.async.
// Requires su0/su1 (2×13³) in shared; su points at the active buffer.
// Override PT_FUSED_{X,Y,Z}3 before include for KO-FP32 etc.
#ifndef PT_FUSED_X3
#define PT_FUSED_X3 device::__pt_fused_x3
#define PT_FUSED_Y3 device::__pt_fused_y3
#define PT_FUSED_Z3 device::__pt_fused_z3
#endif
const DEVICE_REAL inv_dx = 1.0 / blk->m_dx[0];
const DEVICE_REAL inv_dy = 1.0 / blk->m_dx[1];
const DEVICE_REAL inv_dz = 1.0 / blk->m_dx[2];
DEVICE_REAL* __restrict__ su0 = su;
DEVICE_REAL* __restrict__ su1 = su + (nx * nx * nx);
DEVICE_REAL* __restrict__ su_cur = su0;
DEVICE_REAL* __restrict__ su_nxt = su1;
"""


def split_segments(body: str) -> list[tuple[str, str]]:
    """Return [(varname, segment_without_ld), ...] for each load."""
    ld_re = re.compile(
        r"device::__ld_blk_var1__<DEVICE_REAL,\s*pw,\s*nx>\(su,\s*(\w+),\s*blk\);"
    )
    matches = list(ld_re.finditer(body))
    out = []
    for i, m in enumerate(matches):
        var = m.group(1)
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(body)
        out.append((var, body[start:end]))
    return out


def retarget_su(segment: str) -> str:
    """Stencil helpers take the active shared buffer as first arg after template."""
    seg = re.sub(
        r"\bPT_FUSED_([XYZ])3<nx>\(su,",
        r"PT_FUSED_\g<1>3<nx>(su_cur,",
        segment,
    )
    seg = re.sub(
        r"device::__pt_d([xyz]{2})<nx>\(su,",
        r"device::__pt_d\1<nx>(su_cur,",
        seg,
    )
    return seg


def inject_prefetch(segment: str, next_var: str | None) -> str:
    """After first post-stencil __syncthreads, issue prefetch of next_var."""
    seg = retarget_su(segment)
    if not next_var:
        return seg

    m = re.search(r"__syncthreads\(\);\s*\n", seg)
    if not m:
        raise RuntimeError(f"no syncthreads in segment before {next_var}")
    insert_at = m.end()
    prefetch = (
        f"device::__ld_blk_var1_async_issue__<nx>(su_nxt, {next_var});\n"
    )
    seg = seg[:insert_at] + prefetch + seg[insert_at:]
    footer = (
        "device::__ld_blk_var1_async_wait__();\n"
        "{ DEVICE_REAL* __tmp = su_cur; su_cur = su_nxt; su_nxt = __tmp; }\n"
    )
    return seg + footer


def main() -> None:
    src = (HERE / "gauge6_point.cpp").read_text()
    # Drop the auto header through inv_dz lines — keep body from first ld
    ld0 = src.find("device::__ld_blk_var1__")
    if ld0 < 0:
        raise SystemExit("no loads in gauge6_point.cpp")
    body = src[ld0:]
    segs = split_segments(body)
    print(f"segments: {len(segs)}")

    parts = [HEADER]
    # Prime first buffer
    v0 = segs[0][0]
    parts.append(
        f"device::__ld_blk_var1_async_issue__<nx>(su_cur, {v0});\n"
        f"device::__ld_blk_var1_async_wait__();\n"
    )
    for i, (var, seg) in enumerate(segs):
        nxt = segs[i + 1][0] if i + 1 < len(segs) else None
        parts.append(f"// ---- field {var} (db) ----\n")
        parts.append(inject_prefetch(seg, nxt))

    out = "".join(parts)
    # Safety: no bare (su, left in stencil helpers
    dst = HERE / "gauge6_point_db.cpp"
    dst.write_text(out)
    print(f"wrote {dst} ({dst.stat().st_size} bytes)")
    print(f"async issues: {out.count('__ld_blk_var1_async_issue__')}")
    print(f"waits: {out.count('__ld_blk_var1_async_wait__')}")


if __name__ == "__main__":
    main()
